roles=[
 ('RL-01','Responsible owner/operating manager','Own controlled configuration/manual, appoint qualified people, maintain authority/insurance records and prohibit dispatch on unresolved critical defects.'),
 ('RL-02','Designated driver','Control train only under accepted operating mode, acknowledge dispatch/stop communication, verify vehicle readiness and stop/no-dispatch on disagreement. Brake controls and limits must be trained on the actual accepted train.'),
 ('RL-03','Conductor / boarding lead','Coordinate passenger count and accessible assistance, clear doors/platforms/stairs, maintain passenger protection and give the single defined boarding-clear confirmation. Not automatically the driver.'),
 ('RL-04','Route / station dispatch function','Protect route occupancy, crossings, station and work limits; confirm route availability and record movements. Future second-train operation requires a separate accepted separation design.'),
 ('RL-05','Qualified maintenance and energy-control lead','Control defect isolation, lifting/restraint/energy-specific service, configuration and restoration. Specialist wheel/axle, spring-brake, structural/NDT and electrical tasks retain their qualified personnel.'),
 ('RL-06','Incident / rescue lead and trained responders','Coordinate protected site/evacuation/rescue decisions, emergency services access, communications and accounting. Exact rescue method/equipment and assistance training must be accepted before passenger use.')]
save('roles-and-training.json',dict(issue=ISSUE,roles=[dict(id=id,role=role,development_responsibility=text,named_person=None,qualified_training_record=None) for id,role,text in roles],staffing_count=None,role_combination='Only if an accepted staffing/visibility/workload assessment demonstrates all functions remain covered; no default one-person operation.',training_topics=['Actual controls and limitations, route/sight lines and communication','Every-vehicle service/release/readiness checks and spring parking limitations','Boarding/door/stair/lift interlocks and accessible assistance/evacuation','Defect reporting, stop authority and prohibited resets/bypasses','Energy-specific maintenance, lifting/support and OEM spring-brake service for qualified personnel','Incident command, protected evacuation, emergency access and return-to-service discipline'],training_acceptance=None))

modes=[
 ('MD-00','Unreleased development','Current project state: no actual released passenger train. Nonstructural mockups/research only within their specific safe scope.','No passenger/field operation from this Site.'),
 ('MD-01','Out of service / protected work','Recorded defect or maintenance; protected track/work area, independent vehicle restraint and energy-specific isolation accepted for task.','No dispatch; only separately authorized guarded work/test mode.'),
 ('MD-02','Secured inspection / charging','Actual configured consist restrained, people clear, protected route and approved charge/functional-check procedure.','No automatic traction permission from charging or static pressure.'),
 ('MD-03','Secured boarding','At accepted interface, stopped and physically held by accepted parking/holding arrangement; route and passenger area protected.','No departure with any door/gate/stair/lift unsecured, unclear boarding signal or unresolved fault.'),
 ('MD-04','Authorized normal run','Accepted route/mode/direction, every-vehicle brake release/reserve/continuity and boarding clear; designated driver and dispatch functions confirm.','Any credible stop request, readiness loss or route/communication conflict removes dispatch permission under accepted response.'),
 ('MD-05','Stopped incident / emergency','Accepted stop response invoked; protect route and people, assess whether remaining aboard or evacuation is safer. Verify and maintain accepted holding/restraint for controlled assisted unloading, with actual changing floor/suspension state; urgent fire/smoke escape follows its separate accepted emergency priority.','No reset-and-go, generic caging/towing or unapproved movement to a station.'),
 ('MD-06','Specialist rescue / recovery','Separate engineered plan, independent restraint, qualified people/equipment and protected route; actual isolated brakes and vehicle damage recorded.','No passenger-service permission and no improvised rerailing/lifting/pushing.'),
 ('MD-07','Return-to-service hold','Repairs/configuration/inspection and required regression complete, actual brakes restored, accountable signoffs and actual readiness rechecked.','Only specifically accepted configuration may re-enter inspection/boarding/run modes.')]
