cards=''.join('<article class="card" id="readiness-'+p['id'].lower()+'"><p class="eyebrow">'+p['id']+' · CONDITIONAL DEVELOPMENT, NOT FIELD-READY</p><h2>'+E(p['title'])+'</h2><p>Trigger: '+E(p['trigger'])+'</p><p>Roles: '+E(', '.join(p['role_ids']))+'</p><ol>'+''.join('<li>'+E(s)+'</li>' for s in p['development_sequence'])+'</ol><p><strong>Hold:</strong> '+E(p['stop_or_hold'])+'</p><p>Reuse: '+E('; '.join(p['existing_records_to_reuse']))+'</p></article>' for p in procedures)
